/// and extend the expiry time of all active connections to the exp
/// claim in the new token.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct RefreshTokenPayload {
    /// e.g. avoid timeout, key rotation, etc.
    #[prost(string, tag = "1")]
    pub reason: ::prost::alloc::string::String,
}
///
/// Response to the RefreshToken request.
/// If the client has any active streaming connections, the connected field
/// will be true and the exp field will be the time that the new token will expire.
#[derive(Clone, Copy, PartialEq, ::prost::Message)]
pub struct ConnectionStatus {
    /// True if client has any active streaming connections
    #[prost(bool, tag = "1")]
    pub connected: bool,
    /// Time that new token will expire
    #[prost(uint64, tag = "2")]
    pub exp: u64,
}
///
/// Request to revoke access for a subject.
/// If revoke_all is true, all active connections for the subject will be revoked.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct RevokeAccessPayload {
    /// e.g. user id, device id, etc.
    #[prost(string, tag = "1")]
    pub subject: ::prost::alloc::string::String,
    /// e.g. avoid timeout, key rotation, etc.
    #[prost(string, tag = "2")]
    pub reason: ::prost::alloc::string::String,
    /// True to revoke access for all subjects
    #[prost(bool, tag = "3")]
    pub revoke_all: bool,
}
///
/// Response to the RevokeAccess request.
/// Lists sub fields of remaining and revoked subjects.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct RevocationResponse {
    /// user / system ids still connected
    #[prost(string, repeated, tag = "1")]
    pub remaining_subjects: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
    /// user / system ids that were revoked
    #[prost(string, repeated, tag = "2")]
    pub revoked_subjects: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
}
